const FLOW_UNITS={mass:{kgs:1,kgh:1/3600,lbs:.45359237,lbh:.45359237/3600},volume:{m3s:1,m3h:1/3600,ls:.001,lmin:.001/60,ft3min:.3048**3/60},velocity:{ms:1,fts:.3048},diameter:{m:1,mm:.001,inch:.0254},density:{kgm3:1,lbft3:.45359237/.3048**3},dynamic:{Pas:1,mPas:.001,cP:.001},kinematic:{m2s:1,mm2s:1e-6,cSt:1e-6}};
