// src/gases.js
// Frozen ideal-gas thermodynamics: NASA7 / NASA TM-4513. MPa, K, kg, kJ.
const GAS_R=8.31446261815324, GAS_P0=.101325;
const AIR={N2:.78084,O2:.20946,Ar:.00934,CO2:.00036};
const FLUE={N2:.73,CO2:.10,H2O:.12,O2:.05};
function gasComposition(fractions,basis='mole'){
 if(!['mole','mass'].includes(basis))throw Error('Базис складу: молярний або масовий.');
 if(!fractions||typeof fractions!=='object'||Array.isArray(fractions))throw Error('Задайте склад суміші.');
 const entries=Object.entries(fractions).map(([id,x])=>{const d=GAS_DATA.find(s=>s.id===id);if(!d||!Number.isFinite(x)||x<0)throw Error('Невідома речовина або некоректна частка: '+id);return {d,x};});
 const total=entries.reduce((a,b)=>a+b.x,0);if(Math.abs(total-1)>1e-8)throw Error('Сума часток має дорівнювати 1 (100 %).');
 const positive=entries.filter(s=>s.x>0);if(!positive.length)throw Error('Суміш порожня.');
 const divisor=basis==='mass'?positive.reduce((a,b)=>a+b.x/b.d.M,0):1;
 return positive.map(({d,x})=>({d,x:basis==='mass'?x/d.M/divisor:x}));
}
function gasLimits(fractions,basis='mole') {const c=gasComposition(fractions,basis);return {min:Math.max(...c.map(q=>q.d.range[0])),max:Math.min(...c.map(q=>q.d.range.at(-1)))};}
function speciesNASA(d,T){const a=d.coeff[T<=d.range[1]?0:1];return {cp:GAS_R*(a[0]+a[1]*T+a[2]*T**2+a[3]*T**3+a[4]*T**4),h:GAS_R*T*(a[0]+a[1]*T/2+a[2]*T**2/3+a[3]*T**3/4+a[4]*T**4/5+a[5]/T),s:GAS_R*(a[0]*Math.log(T)+a[1]*T+a[2]*T**2/2+a[3]*T**3/3+a[4]*T**4/4+a[6])};}
function gasState(p,T,fractions=AIR,basis='mole'){
 if(!Number.isFinite(p)||p<=0||!Number.isFinite(T))throw Error('Газ: потрібні скінченні T та додатний абсолютний P.');
 const comp=gasComposition(fractions,basis),lim=gasLimits(fractions,basis);
 if(T<lim.min||T>lim.max)throw Error(`NASA7: для цього складу T = ${lim.min}…${lim.max} K; екстраполяція заборонена.`);
 let M=0,cp=0,h=0,s=0;for(const q of comp){const z=speciesNASA(q.d,T);M+=q.x*q.d.M;cp+=q.x*z.cp;h+=q.x*z.h;s+=q.x*(z.s-GAS_R*Math.log(q.x*p/GAS_P0));}
 const R=GAS_R/M;cp/=M;h/=M;s/=M;const cv=cp-R,rho=1000*p/(R*T),v=1/rho;
 if(!(cv>0&&cp>cv))throw Error('NASA7: нефізична теплоємність.');
 return {model:'NASA7 · ідеальний газ',p,T,M,R,cp,cv,h,s,rho,v,u:h-R*T,w:Math.sqrt(cp/cv*R*T*1000),gamma:cp/cv,Z:1,composition:Object.fromEntries(comp.map(q=>[q.d.id,q.x])),basis:'mole',limits:lim,mu:null,lambda:null};
}
function gasInverse(p,target,key,fractions=AIR,basis='mole'){
 if(!['h','s'].includes(key)||!Number.isFinite(target))throw Error('Газова інверсія: скінченні h або s.');
 const lim=gasLimits(fractions,basis);let lo=lim.min,hi=lim.max;
 if(target<gasState(p,lo,fractions,basis)[key]-1e-10||target>gasState(p,hi,fractions,basis)[key]+1e-10)throw Error('Задана величина поза діапазоном NASA7.');
 let T=(lo+hi)/2;for(let k=0;k<90;k++){const q=gasState(p,T,fractions,basis),error=q[key]-target;if(Math.abs(error)<1e-9)return q;if(error<0)lo=T;else hi=T;const n=T-error/(key==='h'?q.cp:q.cp/T);T=n>lo&&n<hi?n:(lo+hi)/2;}
 throw Error('Газова інверсія не збіглася.');
}


// src/real-gases.js
// Pure-fluid HEOS calculations, using the same local MIT CoolProp WASM as humid air.
const REAL_GAS_FLUIDS={N2:'Nitrogen',O2:'Oxygen',CO2:'CarbonDioxide',CO:'CarbonMonoxide',H2:'Hydrogen',H2O:'Water',CH4:'Methane',Ar:'Argon',He:'Helium',SO2:'SulfurDioxide',Ne:'Neon'};
// Huber et al. (2018), Tables 5/6, doi:10.1063/1.5036625; only matching CoolProp correlations.
const GAS_TRANSPORT_LIMITS={N2:{mu:[50,2000,2200],lambda:[50,2000,2200]},O2:{mu:[54.36,1000,82],lambda:[54.36,2000,82]},Ar:{mu:[55,2000,1000],lambda:[55,2000,1000]},CO2:{mu:[100,2000,8000],lambda:[216.59,1100,200]},H2:{mu:[13.96,1000,200],lambda:[13.96,1000,100]},He:{mu:[.8,1500,2000],lambda:[2.18,830,127]},CH4:{lambda:[91,700,100]}};
function realGasState(id,p,value,mode='pt'){
 const name=REAL_GAS_FLUIDS[id];if(!name)throw Error('Для '+id+' модель реального газу не підключена. Оберіть NASA7 явно.');
 if(!['pt','ph','ps'].includes(mode)||!Number.isFinite(p)||p<=0||!Number.isFinite(value))throw Error('Потрібні додатний абсолютний тиск і скінченний другий параметр.');
 return evaluateRealFluid(id,name,p,value,mode,{[id]:1});
}
function evaluateRealFluid(id,name,p,value,mode,composition){
 const cp=getCoolPropBackend(),fluid='HEOS::'+name;
 const valid=n=>Number.isFinite(n)&&Math.abs(n)<1e100;
 const constant=key=>{const n=cp.PropsSI(key,'',0,'',0,fluid);if(!valid(n))throw Error('Не вдалося прочитати межі моделі '+name);return n;};
 const min=constant('Tmin'),max=constant('Tmax'),pmax=constant('pmax')/1e6;
 if(p>pmax||mode==='pt'&&(value<min||value>max))throw Error(`Модель ${id}: T=${min}…${max} K; P≤${pmax} МПа. Екстраполяція заборонена.`);
 const key=mode==='pt'?'T':mode==='ph'?'Hmass':'Smass',input=mode==='pt'?value:value*1000;
 const get=(output,optional=false)=>{let n;try{n=cp.PropsSI(output,'P',p*1e6,key,input,fluid);}catch{}if(!valid(n)){if(optional)return null;throw Error('Не знайдено стан '+id+'. Перевірте входи; на лінії насичення P–T не визначає фазу однозначно.');}return n;};
 const T=get('T'),rho=get('Dmass');if(T<min||T>max||rho<=0)throw Error('Результат поза межами рівняння стану.');
 const h=get('Hmass')/1000,s=get('Smass')/1000;
 if(mode!=='pt'&&Math.abs((mode==='ph'?h:s)-value)>1e-6*Math.max(1,Math.abs(value)))throw Error('Обернений розрахунок не задовольняє заданий вхід.');
 const quality=get('Q',true),twoPhase=quality!=null&&quality>=0&&quality<=1;
 const c=twoPhase?null:get('Cpmass',true),v=twoPhase?null:get('Cvmass',true);
 const transportLimits=GAS_TRANSPORT_LIMITS[id]||{};
 const transportGet=(key,output)=>{const lim=transportLimits[key];return twoPhase||lim&&(T<lim[0]||T>lim[1]||p>lim[2])?null:get(output,true);};
 const transportRange=Object.entries(transportLimits).map(([k,b])=>`${k==='mu'?'μ':'λ'}: ${b[0]}…${b[1]} K, P≤${b[2]} МПа.`).join(' ');
 const phase=twoPhase?'Двофазний стан':({0:'Рідина',1:'Надкритичний флюїд',2:'Надкритичний газ',3:'Надкритична рідина',4:'Критична точка',5:'Газ',6:'Двофазний стан',7:'Невизначено'})[get('Phase')]||'Невизначено';
 return {model:'CoolProp 8 · HEOS · '+name,p,T,M:constant('molar_mass')*1000,h,s,u:get('Umass')/1000,rho,v:1/rho,cp:c==null?null:c/1000,cv:v==null?null:v/1000,w:twoPhase?null:get('A',true),gamma:c!=null&&v>0?c/v:null,Z:get('Z',true),mu:transportGet('mu','VISCOSITY'),lambda:transportGet('lambda','CONDUCTIVITY'),transportLimits,transportModels:id==='CH4'?{mu:'Quiñones-Cisneros–Deiters 2006',lambda:'Friend–Ely–Ingham 1989'}:id==='He'?{mu:'Arp–McCarty–Friend 1998',lambda:'Hands–Arp 1981 · критичний доданок CoolProp 8'}:null,quality:twoPhase?quality:null,phase,composition,validation:{source:'https://coolprop.org/fluid_properties/fluids/'+(REAL_GAS_FLUIDS[id]||'Air')+'.html',status:id==='CH4'?'NIST: 3 стани; λ: 4 первинні контролі Friend (1989) у границі розрідженого газу.':['N2','O2','Ar'].includes(id)?'NIST: 3 стани; транспорт: первинна таблиця Lemmon–Jacobsen (2004).':'NIST: 3 стани; первинні транспортні контролі ще не перевірені.',transport:transportRange+' '+(id==='CH4'?'μ: Quiñones-Cisneros–Deiters (2006), λ: Friend–Ely–Ingham (1989). Модель μ відрізняється від описаної для REFPROP (2011). У 3 станах NIST: μ до 6,15 %, λ до 1,39 %. Різниця відтворюється у прямому ядрі; причина λ ще не встановлена.':id==='He'?'λ: Hands–Arp (1981) з критичним доданком CoolProp 8; μ: Arp–McCarty–Friend (1998). При 5,3 K і 0,25 МПа λ відрізняється від NIST на 12,23 %. Питання до критичного доданка зазначено авторами ядра; точну причину розбіжності ще не доведено.':'Розбіжність із NIST та невизначеність кореляції — різні величини.')},limits:{min,max,pmax},notes:['Чиста речовина; фаза: '+phase+'.','h та s — у системі відліку цієї моделі CoolProp; значення NASA7 мають інший базис.','Теплоємності, звук і транспортні властивості двофазної суміші не наведено. Недоступні властивості позначено «—».']};
}

function realGasMixture(p,T,fractions,basis='mole'){
 if(!Number.isFinite(p)||p<=0||p>5||!Number.isFinite(T)||T<250||T>600)throw Error('Дослідний режим сумішей: P=0…5 МПа (P>0), T=250…600 K, лише P–T та газова фаза.');
 const comp=gasComposition(fractions,basis);
 if(comp.some(q=>!['N2','O2','Ar','CO2','H2O'].includes(q.d.id)))throw Error('HEOS суміші: підтримуються N2, O2, Ar, CO2, H2O; інші компоненти потребують окремої перевірки.');
 const name=comp.map(q=>REAL_GAS_FLUIDS[q.d.id]+'['+q.x+']').join('&');
 const q=evaluateRealFluid('mixture',name,p,T,'pt',Object.fromEntries(comp.map(z=>[z.d.id,z.x])));
 if(!['Газ','Надкритичний газ','Надкритичний флюїд'].includes(q.phase))throw Error('Режим сумішей перевірено лише для газової фази.');
 q.model='CoolProp 8 · HEOS · реальна суміш (дослідний режим)';q.limits={min:250,max:600,pmax:5};
 q.validation={source:'https://coolprop.org/fluid_properties/Mixtures.html',status:'Перевірка інтеграції; незалежна точність сумішей не підтверджена.',transport:'Транспортні властивості суміші не сертифіковано; не наведено.'};
 q.mu=null;q.lambda=null;q.notes=['Молярний склад нормовано з обраного базису; тільки однофазний газ.','Дослідний режим: P–h/P–s, конденсація та реакції сумішей не реалізовані.','Система відліку h/s — CoolProp. Межі інтерфейсу не є оцінкою фізичної похибки.'];return q;
}


// src/humid-air.js
// Educational ideal moist-air model. IAPWS-95 saturation / liquid enthalpy,
// NASA7 integrated dry-air and water-vapour ideal-gas cp; not a virial humid-air EOS.
const HA_MIN=273.16, HA_MAX=373.15;
function haEnthalpy(T,W){const air=gasState(.101325,T,AIR),air0=gasState(.101325,HA_MIN,AIR),v=gasState(.101325,T,{H2O:1}),v0=gasState(.101325,HA_MIN,{H2O:1});const latent=saturationT95(HA_MIN).latentHeat;return air.h-air0.h+W*(latent+v.h-v0.h);}
function haRatio(T,p,rh){const pv=rh*saturationT95(T).p;if(pv>=p)throw Error('Парціальний тиск пари має бути нижчим за загальний тиск.');const ratio=gasState(.1,300,{H2O:1}).M/gasState(.1,300,AIR).M;return {pv,W:ratio*pv/(p-pv)};}
function humidAir(p,T,rh){
 if(![p,T,rh].every(Number.isFinite)||p<.05||p>.2||T<HA_MIN||T>HA_MAX||rh<0||rh>1)throw Error('Вологе повітря: P=0,05…0,2 МПа, T=273,16…373,15 K, RH=0…1. Лід не моделюється.');
 const {pv,W}=haRatio(T,p,rh),h=haEnthalpy(T,W),a=gasState(p,T,AIR),v=a.R*T/(1000*(p-pv));
 let dew=null;if(pv>=saturationT95(HA_MIN).p){let lo=HA_MIN,hi=T;for(let i=0;i<55;i++){const m=(lo+hi)/2;if(saturationT95(m).p<pv)lo=m;else hi=m;}dew=(lo+hi)/2;}
 const wetError=t=>{const w=haRatio(t,p,1).W,liquid=saturationT95(t).liquid.h-saturationT95(HA_MIN).liquid.h;return haEnthalpy(t,w)-(w-W)*liquid-h;};
 let wet=null;if(wetError(HA_MIN)<=0){let lo=HA_MIN,hi=T;for(let i=0;i<50;i++){const m=(lo+hi)/2;if(wetError(m)>0)hi=m;else lo=m;}wet=(lo+hi)/2;}
 return {model:'Ідеальне вологе повітря · NASA7 + IAPWS-95',p,T,rh,pv,W,h,dew,wet,v,rho:(1+W)/v,cp:gasState(p,T,AIR).cp+W*gasState(p,T,{H2O:1}).cp,notes:['h, Cp та v віднесені до 1 кг сухого повітря; ρ — маса всієї суміші на об’єм.','Нуль ентальпії: сухе повітря і рідина при 273,16 K.','Ідеальна суміш без віріальних поправок. Точка роси / мокрого термометра нижче 273,16 K не наведена.']};
}


// src/cycles.js
function cycleChecks(values){if(!values.every(Number.isFinite))throw Error('Цикл: потрібні скінченні числа.');}
function efficiencies(a,b,flow){if(a<=0||a>1||b<=0||b>1||flow<=0)throw Error('0 < ККД агрегатів ≤ 1; витрата > 0.');}
function balances(states,works,heat,flow,model,assumptions){const net=works.turbine-works.compressor, rejected=heat-net;if(!(heat>0&&net>0&&rejected>=0))throw Error('Задані параметри не утворюють енергетичний цикл з додатною корисною роботою.');return {states:states.map(q=>({...q,model:q.model||model})),...works,heat,rejected,net,efficiency:net/heat,power:flow*net,flow,model,assumptions};}
function rankine(pHigh,pLow,Tmax,etaT=.85,etaPump=.8,flow=1,model='IF97'){
 cycleChecks([pHigh,pLow,Tmax,etaT,etaPump,flow]);efficiencies(etaT,etaPump,flow);if(pHigh<=pLow)throw Error('Тиск котла має перевищувати тиск конденсатора.');
 const one=calculate('px',pLow,0,model).state;
 const pumpIdeal=calculate('ps',pHigh,one.s,model).state,two=calculate('ph',pHigh,one.h+(pumpIdeal.h-one.h)/etaPump,model).state;
 const three=calculate('pt',pHigh,Tmax,model).state;if(!three||three.h<=two.h||three.rho>322&&Tmax<647.096)throw Error('На вході турбіни потрібна пара або надкритичний флюїд.');
 const turbineIdeal=calculate('ps',pLow,three.s,model).state,four=calculate('ph',pLow,three.h-etaT*(three.h-turbineIdeal.h),model).state;
 return balances([one,two,three,four],{compressor:two.h-one.h,turbine:three.h-four.h},three.h-two.h,flow,model,['Простий цикл Ренкіна без регенерації та проміжного перегріву.','Без втрат тиску і тепла в трубопроводах; насос і турбіна задаються ізоентропними ККД.']);
}
function rankineReheat(pHigh,pReheat,pLow,Tmax,Treheat,etaT=.85,etaPump=.8,flow=1,model='IF97'){
 cycleChecks([pHigh,pReheat,pLow,Tmax,Treheat,etaT,etaPump,flow]);efficiencies(etaT,etaPump,flow);
 if(!(pHigh>pReheat&&pReheat>pLow))throw Error('Потрібно: тиск котла > тиск перегріву > тиск конденсатора.');
 const one=calculate('px',pLow,0,model).state;
 const pumpIdeal=calculate('ps',pHigh,one.s,model).state,two=calculate('ph',pHigh,one.h+(pumpIdeal.h-one.h)/etaPump,model).state;
 const three=calculate('pt',pHigh,Tmax,model).state;if(!three||three.h<=two.h||three.rho>322&&Tmax<647.096)throw Error('На вході турбіни потрібна пара або надкритичний флюїд.');
 const hpIdeal=calculate('ps',pReheat,three.s,model).state,hpOut=calculate('ph',pReheat,three.h-etaT*(three.h-hpIdeal.h),model).state;
 const reheated=calculate('pt',pReheat,Treheat,model).state;if(!reheated||reheated.h<=hpOut.h)throw Error('Температура перегріву має давати додатний підігрів після циліндра високого тиску.');
 const lpIdeal=calculate('ps',pLow,reheated.s,model).state,four=calculate('ph',pLow,reheated.h-etaT*(reheated.h-lpIdeal.h),model).state;
 const turbineWork=(three.h-hpOut.h)+(reheated.h-four.h),heat=(three.h-two.h)+(reheated.h-hpOut.h);
 return balances([one,two,three,hpOut,reheated,four],{compressor:two.h-one.h,turbine:turbineWork},heat,flow,model,['Цикл Ренкіна з одним проміжним перегрівом між циліндрами високого й низького тиску.','Без втрат тиску й тепла в трубопроводах; насос і обидва ступені турбіни — ізоентропні ККД.']);
}
function rankineRegen(pHigh,pExtract,pLow,Tmax,etaT=.85,etaPump=.8,flow=1,model='IF97'){
 cycleChecks([pHigh,pExtract,pLow,Tmax,etaT,etaPump,flow]);efficiencies(etaT,etaPump,flow);
 if(!(pHigh>pExtract&&pExtract>pLow))throw Error('Потрібно: тиск котла > тиск витяжки > тиск конденсатора.');
 const condOut=calculate('px',pLow,0,model).state;
 const cpIdeal=calculate('ps',pExtract,condOut.s,model).state,cpOut=calculate('ph',pExtract,condOut.h+(cpIdeal.h-condOut.h)/etaPump,model).state;
 const inlet=calculate('pt',pHigh,Tmax,model).state;if(!inlet||inlet.h<=cpOut.h||inlet.rho>322&&Tmax<647.096)throw Error('На вході турбіни потрібна пара або надкритичний флюїд.');
 const extractIdeal=calculate('ps',pExtract,inlet.s,model).state,extractState=calculate('ph',pExtract,inlet.h-etaT*(inlet.h-extractIdeal.h),model).state;
 const lpIdeal=calculate('ps',pLow,extractState.s,model).state,lpOut=calculate('ph',pLow,extractState.h-etaT*(extractState.h-lpIdeal.h),model).state;
 const fwhOut=calculate('px',pExtract,0,model).state;
 const y=(fwhOut.h-cpOut.h)/(extractState.h-cpOut.h);
 if(!(y>0&&y<1))throw Error('Тиск витяжки не утворює фізичний баланс підігрівача (0<y<1); оберіть тиск між тиском котла і конденсатора.');
 const fpIdeal=calculate('ps',pHigh,fwhOut.s,model).state,fpOut=calculate('ph',pHigh,fwhOut.h+(fpIdeal.h-fwhOut.h)/etaPump,model).state;
 const turbineWork=(inlet.h-extractState.h)+(1-y)*(extractState.h-lpOut.h),pumpWork=(1-y)*(cpOut.h-condOut.h)+(fpOut.h-fwhOut.h),heat=inlet.h-fpOut.h;
 return balances([inlet,extractState,lpOut,condOut,cpOut,fwhOut,fpOut],{compressor:pumpWork,turbine:turbineWork},heat,flow,model,[`Цикл Ренкіна з одним відкритим регенеративним підігрівачем живильної води; витяжка пари y=${(y*100).toFixed(2)}% маси потоку при p=${pExtract} МПа.`,'Підігрівач виводить насичену рідину (без підрівня/перегріву). Без втрат тиску й тепла в трубопроводах; насоси і турбіна — ізоентропні ККД.']);
}
function brayton(pLow,ratio,Tmin,Tmax,etaT=.9,etaC=.85,flow=1,composition=AIR){
 cycleChecks([pLow,ratio,Tmin,Tmax,etaT,etaC,flow]);efficiencies(etaT,etaC,flow);if(ratio<=1||Tmax<=Tmin)throw Error('Ступінь підвищення тиску > 1 та T₃ > T₁.');
 const pHigh=pLow*ratio,one=gasState(pLow,Tmin,composition),ci=gasInverse(pHigh,one.s,'s',composition),two=gasInverse(pHigh,one.h+(ci.h-one.h)/etaC,'h',composition);
 const three=gasState(pHigh,Tmax,composition),ti=gasInverse(pLow,three.s,'s',composition),four=gasInverse(pLow,three.h-etaT*(three.h-ti.h),'h',composition);
 return balances([one,two,three,four],{compressor:two.h-one.h,turbine:three.h-four.h},three.h-two.h,flow,one.model,['Замкнений цикл Брайтона, ідеальний газ зі сталим складом і змінною Cp(T).','Підігрів моделюється підведенням тепла; горіння, реакції й дисоціація не моделюються.']);
}


// src/phase-boundaries.js
// IAPWS R14-08(2011), Eqs. 1–6; R16-17(2018), Section 6, Eqs. 9–13.
// Pressures in MPa, temperatures in K. D2O curves are auxiliary representations
// printed in the release, not separately endorsed IAPWS recommendations.
const H2O_CURVES={Ih:[251.165,273.16],III:[251.165,256.164],V:[256.164,273.31],VI:[273.31,355],VII:[355,715]};
const D2O_CURVES={Ih:[254.415,276.969],III:[254.415,258.661],V:[258.661,275.748],VI:[275.748,315]};
const D2O_PHASE_NOTE='Криві D₂O: допоміжні кореляції R16-17, §6; окрема офіційна рекомендація IAPWS для цих кривих відсутня.';
function meltingPressure(T,phase='Ih',substance='H2O'){
 const ranges=substance==='H2O'?H2O_CURVES:substance==='D2O'?D2O_CURVES:null,range=ranges?.[phase];
 if(!range||!Number.isFinite(T)||T<range[0]||T>range[1])throw Error(`Плавлення ${substance}, лід ${phase}: потрібно ${range?.join('…')||'коректну фазу й речовину'} K.`);
 if(substance==='D2O'){
  if(phase==='Ih'){const t=T/276.969;return .00066159*(1-30153*(1-t**5.5)+692503*(1-t**8.2));}
  const [t,p,a,b]=phase==='III'?[254.415,222.41,.802871,33]:phase==='V'?[258.661,352.19,1.280388,7.6]:[275.748,634.53,1.276026,4];
  return p*(1-a*(1-(T/t)**b));
 }
 if(phase==='Ih'){const t=T/273.16;return .000611657*(1+1195393.37*(1-t**3)+80818.3159*(1-t**25.75)+3338.2686*(1-t**103.75));}
 if(phase==='VII'){const t=T/355;return 2216*Math.exp(1.73683*(1-t**-1)-.0544606*(1-t**5)+8.06106e-8*(1-t**22));}
 const [t,p,a,b]=phase==='III'?[251.165,208.566,.299948,60]:phase==='V'?[256.164,350.1,1.18721,8]:[273.31,632.4,1.07476,4.6];
 return p*(1-a*(1-(T/t)**b));
}
function sublimationPressure(T,substance='H2O'){
 const min=substance==='H2O'?50:210,max=substance==='H2O'?273.16:276.969;
 if(!['H2O','D2O'].includes(substance)||!Number.isFinite(T)||T<min||T>max)throw Error(`Сублімація ${substance}: потрібно ${min}…${max} K.`);
 const t=T/max;
 return substance==='H2O'?.000611657*Math.exp((-21.2144006*t**.00333333333+27.3203819*t**1.20666667-6.1059813*t**1.70333333)/t):.00066159*Math.exp(-13.14226*(1-t**-1.73)+32.12969*(1-t**-1.42));
}
function meltingTemperature(p,substance='H2O'){
 const ranges=substance==='H2O'?H2O_CURVES:D2O_CURVES;
 if(!Number.isFinite(p)||p<=0)throw Error('Тиск плавлення має бути додатним.');
 for(const [phase,[min,max]] of Object.entries(ranges)){
  const a=meltingPressure(min,phase,substance),b=meltingPressure(max,phase,substance);
  if(p<Math.min(a,b)||p>Math.max(a,b))continue;
  let lo=min,hi=max;
  for(let i=0;i<65;i++){const mid=(lo+hi)/2,q=meltingPressure(mid,phase,substance);if((q>p)===(b>a))hi=mid;else lo=mid;}
  return {T:(lo+hi)/2,phase};
 }
 throw Error('Тиск поза межами наведених кривих плавлення.');
}
function boundaryCalculation(substance,kind,T,phase='Ih'){
 if(!['melt','subl'].includes(kind))throw Error('Невідома фазова рівновага.');
 const p=kind==='melt'?meltingPressure(T,phase,substance):sublimationPressure(T,substance);
 return {model:substance==='H2O'?'IAPWS R14-08(2011)':'D₂O · IAPWS R16-17(2018), §6',substance,T,p,phase:kind==='melt'?`Лід ${phase} ↔ рідина`:'Лід Ih ↔ пара',notes:substance==='D2O'?[D2O_PHASE_NOTE]:[]};
}
function icePhaseStatus(T,pPa){
 const p=pPa/1e6,notes=[];
 let phase='Лід Ih';
 if(T>=50){const ps=sublimationPressure(T);if(Math.abs(p-ps)<Math.max(1e-15,ps*1e-7))phase='Межа сублімації: лід Ih ↔ пара';else if(p<ps){phase='Метастабільний лід щодо пари';notes.push('Тиск нижче кривої сублімації R14-08: рівноважною фазою є пара.');}}
 else notes.push('T < 50 K: крива сублімації поза офіційним діапазоном; рівновага з парою не перевірена.');
 if(T>=251.165){const pm=meltingPressure(T);if(Math.abs(p-pm)<Math.max(1e-9,pm*1e-7))phase='Межа плавлення: лід Ih ↔ рідина';else if(p>pm){phase='Метастабільний лід щодо рідини';notes.push('Тиск вище кривої плавлення льоду Ih: задані властивості описують метастабільний лід.');}}
 if(p>208.566)notes.push('Можливі інші модифікації льоду; рівновага між твердими фазами тут не моделюється.');
 return {phase,notes};
}


// src/comparison.js
const COMPARISON_PROPERTIES=[['T','Температура','K'],['p','Тиск','МПа'],['h','Ентальпія','кДж/кг'],['s','Ентропія','кДж/(кг·K)'],['rho','Густина','кг/м³'],['v','Питомий об’єм','м³/кг'],['cp','Cp','кДж/(кг·K)'],['cv','Cv','кДж/(кг·K)'],['w','Швидкість звуку','м/с']];
function compareModels(mode,a,b){
 const models=['IF97','IAPWS-95'].map(model=>{try{const result=calculate(mode,a,b,model);return {model,result};}catch(e){return {model,error:e.message};}});
 const state=r=>r.result?.state;
 const left=state(models[0]),right=state(models[1]);
 const rows=COMPARISON_PROPERTIES.map(([key,label,unit])=>{const x=left?.[key],y=right?.[key],valid=Number.isFinite(x)&&Number.isFinite(y);return {key,label,unit,if97:x??null,iapws95:y??null,delta:valid?x-y:null,relative:valid&&Math.abs(y)>1e-12?100*(x-y)/Math.abs(y):null};});
 const notes=['Δ = IF97 − IAPWS-95; відносне відхилення = 100·Δ/|IAPWS-95|. Відмінність моделей не є оцінкою похибки вимірювання.'];
 if(models.some(z=>z.result?.ambiguous||(!z.result?.state&&z.result?.saturation)))notes.push('На лінії насичення p–T не визначає частку пари. Оберіть p–x або T–x для порівняння однакової сухості.');
 if(left&&right&&left.phase!==right.phase)notes.push('Фазові позначення моделей можуть відрізнятися; поблизу насичення перевірте стан кожної моделі.');
 return {model:'Порівняння IF97 / IAPWS-95',mode,a,b,models,rows,notes};
}


// src/ice.js
// IAPWS R10-06(2009), Revised Release on the Equation of State 2006 for H2O Ice Ih.
// Gibbs energy g(T,p), Eq. (1); complex constants per Table 2; verified against the
// official Table 6 check values (triple point, normal-pressure melting point, 100 K/100 MPa).
const TT_ICE=273.16, PT_ICE=611.657, P0_ICE=101325, PI0_ICE=P0_ICE/PT_ICE;
const G0K=[-0.632020233335886e6,0.655022213658955,-0.189369929326131e-7,0.339746123271053e-14,-0.556464869058991e-21];
const R2K=[[-0.725974574329220e2,-0.781008427112870e2],[-0.557107698030123e-4,0.464578634580806e-4],[0.234801409215913e-10,-0.285651142904972e-10]];
const ICE_S0_IAPWS95=-0.332733756492168e4, ICE_S0_ABSOLUTE=0.18913e3;
const T1=[0.368017112855051e-1,0.510878114959572e-1], ICE_R1=[0.447050716285388e2,0.656876847463481e2], T2=[0.337315741065416,0.335449415919309];
const cadd=(a,b)=>[a[0]+b[0],a[1]+b[1]], csub=(a,b)=>[a[0]-b[0],a[1]-b[1]], cmul=(a,b)=>[a[0]*b[0]-a[1]*b[1],a[0]*b[1]+a[1]*b[0]], cscale=(a,s)=>[a[0]*s,a[1]*s], re=a=>a[0];
const cln=a=>[Math.log(Math.hypot(a[0],a[1])),Math.atan2(a[1],a[0])]; // principal value, Im in (-pi,pi]
const cinv=a=>{const d=a[0]*a[0]+a[1]*a[1];return [a[0]/d,-a[1]/d];};
const rMinusTau=(t,tau)=>[t[0]-tau,t[1]]; // t - tau, tau real
function g0(pi){let s=0;for(let k=0;k<5;k++)s+=G0K[k]*(pi-PI0_ICE)**k;return s;}
function g0p(pi){let s=0;for(let k=1;k<5;k++)s+=k*G0K[k]*(pi-PI0_ICE)**(k-1);return s/PT_ICE;}
function g0pp(pi){let s=0;for(let k=2;k<5;k++)s+=k*(k-1)*G0K[k]*(pi-PI0_ICE)**(k-2);return s/(PT_ICE*PT_ICE);}
function r2(pi){let re_=0,im=0;for(let k=0;k<3;k++){const w=(pi-PI0_ICE)**k;re_+=R2K[k][0]*w;im+=R2K[k][1]*w;}return [re_,im];}
function r2p(pi){let re_=0,im=0;for(let k=1;k<3;k++){const w=k*(pi-PI0_ICE)**(k-1);re_+=R2K[k][0]*w;im+=R2K[k][1]*w;}return [re_/PT_ICE,im/PT_ICE];}
const r2pp=()=>[2*R2K[2][0]/(PT_ICE*PT_ICE),2*R2K[2][1]/(PT_ICE*PT_ICE)];
// bracket(t,tau) = (t-tau)ln(t-tau) + (t+tau)ln(t+tau) - 2t ln(t) - tau^2/t ; and its tau-derivatives.
function bracket(t,tau){const a=rMinusTau(t,tau),b=cadd(t,[tau,0]);return csub(csub(cadd(cmul(a,cln(a)),cmul(b,cln(b))),cscale(cmul(t,cln(t)),2)),cscale(cinv(t),tau*tau));}
function dBracket(t,tau){const a=rMinusTau(t,tau),b=cadd(t,[tau,0]);return csub(csub(cln(b),cln(a)),cscale(cinv(t),2*tau));}
function d2Bracket(t,tau){const a=rMinusTau(t,tau),b=cadd(t,[tau,0]);return csub(cadd(cinv(a),cinv(b)),cscale(cinv(t),2));}
function ice(T,p,s0=ICE_S0_IAPWS95){
 if(!Number.isFinite(T)||!Number.isFinite(p)||T<=0||T>TT_ICE||p<0||p>210e6)throw Error('Лід Ih (IAPWS R10-06): потрібно 0 < T ≤ 273,16 K і 0 ≤ p ≤ 210 МПа.');
 const tau=T/TT_ICE, pi=p/PT_ICE, r2v=r2(pi), r2pv=r2p(pi), r2ppv=r2pp();
 const g=g0(pi)-s0*TT_ICE*tau+TT_ICE*(re(cmul(ICE_R1,bracket(T1,tau)))+re(cmul(r2v,bracket(T2,tau))));
 const gp=g0p(pi)+TT_ICE*re(cmul(r2pv,bracket(T2,tau)));
 const gpp=g0pp(pi)+TT_ICE*re(cmul(r2ppv,bracket(T2,tau)));
 const gT=-s0+re(cmul(ICE_R1,dBracket(T1,tau)))+re(cmul(r2v,dBracket(T2,tau)));
 const gTp=re(cmul(r2pv,dBracket(T2,tau)));
 const gTT=(re(cmul(ICE_R1,d2Bracket(T1,tau)))+re(cmul(r2v,d2Bracket(T2,tau))))/TT_ICE;
 const rho=1/gp, s=-gT, cp=-T*gTT, h=g-T*gT, u=g-T*gT-p*gp, f=g-p*gp;
 const alpha=gTp/gp, beta=-gTp/gpp, kappaT=-gpp/gp, kappaS=(gTp*gTp-gpp*gTT)/(gp*gTT);
 return {...icePhaseStatus(T,p),model:'Лід Ih · IAPWS R10-06(2009)',T,p,g,v:gp,rho,s,cp,h,u,f,alpha,beta,kappaT,kappaS};
}


// src/d2o.js
// IAPWS R16-17(2018), Revised Release on the IAPWS Formulation 2017 for the
// Thermodynamic Properties of Heavy Water. Molar Helmholtz free energy alpha(delta,tau);
// verified against the official Tables 6-8 (ideal/residual derivatives, single-phase
// p/cv/w/s, and saturation p/rho/h/s via the Maxwell criterion).
const D2O_TC=643.847, D2O_RHOC=17.77555, D2O_R=8.3144598, D2O_M=20.027508;
const D2O_C0=4.0, D2O_A1=-8.67099402264600, D2O_A2=6.96033578458778;
const D2O_V=[0.10633e-1,0.99787,0.21483e1,0.3549], D2O_U=[308,1695,3949,10317];
const D2O_GAM=D2O_U.map(u=>u/D2O_TC);
function d2oPhi0(delta,tau){
 let phi=Math.log(delta)+D2O_A1+D2O_A2*tau+(D2O_C0-1)*Math.log(tau);
 let phi_t=D2O_A2+(D2O_C0-1)/tau, phi_tt=-(D2O_C0-1)/(tau*tau);
 for(let i=0;i<4;i++){const g=D2O_GAM[i],v=D2O_V[i],e=Math.exp(-g*tau);phi+=v*Math.log(1-e);phi_t+=v*g*e/(1-e);phi_tt-=v*g*g*e/((1-e)*(1-e));}
 return {phi,phi_d:1/delta,phi_dd:-1/(delta*delta),phi_t,phi_tt,phi_dt:0};
}
// Residual part, Table 2: i=1-6 power terms, i=7-12 power*exp(-delta^l), i=13-24 Gaussian bell terms.
const D2O_T1=[[0.122082060e-1,1.0000,4],[0.296956870e1,0.6555,1],[-0.379004540e1,0.9369,1],[0.941089600,0.5610,2],[-0.922466250,0.7017,2],[-0.139604190e-1,1.0672,3]];
const D2O_T2=[[-0.125203570,3.9515,1,1],[-0.555391500e1,4.6000,1,2],[-0.493009740e1,5.1590,3,2],[-0.359470240e-1,0.2000,2,1],[-0.936172870e1,5.4644,2,2],[-0.691835150,2.3660,1,2]];
const D2O_T3=[[-0.456110600e-1,3.4553,1,0.6014,0.4200,1.5414,1.8663],[-0.224513300e1,1.4150,3,1.4723,2.4318,1.3794,0.2895],[0.860006070e1,1.5745,1,1.5305,1.2888,1.7385,0.5803],[-0.248410420e1,3.4540,3,2.4297,8.2710,1.3045,0.2236],[0.164476900e2,3.8106,1,1.3086,0.3673,2.7242,0.6815],[0.270393360e1,4.8950,1,1.3528,0.9504,3.5321,0.9495],[0.375637470e2,1.4300,2,3.4456,7.8318,2.4552,1.1158],[-0.177607760e1,1.5870,2,1.2645,3.3281,0.8319,0.1607],[0.220924640e1,3.7900,2,2.5547,7.1753,1.3500,0.4144],[0.519652000e1,2.6200,1,1.2148,0.9465,2.5617,0.9683],[0.421097400,1.9000,1,18.738,1177.0,1.0491,0.9488],[-0.391921100,4.3200,1,18.677,1167.0,1.0486,0.9487]];
function d2oPhiR(delta,tau){
 let phi=0,phi_d=0,phi_t=0,phi_dd=0,phi_dt=0,phi_tt=0;
 for(const [n,t,d] of D2O_T1){const P=delta**d,Q=tau**t;phi+=n*P*Q;phi_d+=n*d*delta**(d-1)*Q;phi_t+=n*t*P*tau**(t-1);phi_dd+=n*d*(d-1)*delta**(d-2)*Q;phi_dt+=n*d*t*delta**(d-1)*tau**(t-1);phi_tt+=n*t*(t-1)*P*tau**(t-2);}
 for(const [n,t,d,l] of D2O_T2){const E=Math.exp(-(delta**l)),Q=tau**t,Qm1=tau**(t-1),Qm2=tau**(t-2),A=d-l*delta**l;
  phi+=n*delta**d*Q*E;phi_d+=n*Q*E*delta**(d-1)*A;phi_dd+=n*Q*E*delta**(d-2)*(A*(A-1)-l*l*delta**l);phi_t+=n*t*delta**d*Qm1*E;phi_tt+=n*t*(t-1)*delta**d*Qm2*E;phi_dt+=n*t*delta**(d-1)*Qm1*E*A;}
 for(const [n,t,d,eta,beta,gamma,eps] of D2O_T3){const dd=delta-eps,dt=tau-gamma,psi=Math.exp(-eta*dd*dd-beta*dt*dt),P=delta**d,Q=tau**t;
  const dFac=d*delta**(d-1)-2*eta*dd*P, tFac=t*tau**(t-1)-2*beta*dt*Q;
  phi+=n*P*Q*psi;phi_d+=n*Q*psi*dFac;phi_dd+=n*Q*psi*(d*(d-1)*delta**(d-2)-4*eta*d*delta**(d-1)*dd-2*eta*P+4*eta*eta*P*dd*dd);
  phi_t+=n*P*psi*tFac;phi_tt+=n*P*psi*(t*(t-1)*tau**(t-2)-4*beta*t*tau**(t-1)*dt-2*beta*Q+4*beta*beta*Q*dt*dt);phi_dt+=n*psi*dFac*tFac;}
 return {phi,phi_d,phi_t,phi_dd,phi_dt,phi_tt};
}
function d2oDecorate(T,rhoMolar){
 const tau=D2O_TC/T, delta=rhoMolar/D2O_RHOC, o=d2oPhi0(delta,tau), r=d2oPhiR(delta,tau);
 const p=rhoMolar*D2O_R*T*(1+delta*r.phi_d)/1000; // MPa
 const u=D2O_R*T*tau*(o.phi_t+r.phi_t), h=D2O_R*T*(1+tau*(o.phi_t+r.phi_t)+delta*r.phi_d);
 const s=D2O_R*(tau*(o.phi_t+r.phi_t)-o.phi-r.phi);
 const cv=-D2O_R*tau*tau*(o.phi_tt+r.phi_tt);
 const a=1+delta*r.phi_d-delta*tau*r.phi_dt, b=1+2*delta*r.phi_d+delta*delta*r.phi_dd;
 const cp=cv+D2O_R*a*a/b;
 const w=Math.sqrt(D2O_R*T*(b-a*a/(tau*tau*(o.phi_tt+r.phi_tt)))*1000/D2O_M);
 const rho=rhoMolar*D2O_M; // kg/m3 (mol/dm3 * g/mol numerically equals kg/m3)
 return {model:'D2O (важка вода) · IAPWS R16-17(2018)',T,p,rho,v:1/rho,h:h/D2O_M,u:u/D2O_M,s:s/D2O_M,cv:cv/D2O_M,cp:cp/D2O_M,w,region:rhoMolar};
}
// side-aware Newton with a bracket safeguard: never let a step cross past the saturation
// density of the OTHER phase, so a liquid solve can't collapse onto the vapor root and vice versa.
function d2oDensityAt(p,T,rhoGuess,side,satRho){
 let rho=rhoGuess;
 for(let i=0;i<100;i++){
  const tau=D2O_TC/T,delta=rho/D2O_RHOC,r=d2oPhiR(delta,tau);
  const pCalc=rho*D2O_R*T*(1+delta*r.phi_d)/1000, dpdrho=D2O_R*T*(1+2*delta*r.phi_d+delta*delta*r.phi_dd)/1000;
  const err=pCalc-p; if(Math.abs(err)<Math.max(1e-10,Math.abs(p)*1e-12)&&dpdrho>0)return rho;
  let next=dpdrho>0?rho-err/dpdrho:rho*(err>0?1.5:0.5);
  if(side==='liquid'&&satRho&&next<satRho*(1-1e-9))next=(rho+satRho)/2;
  if(side==='vapor'&&satRho&&next>satRho*(1+1e-9))next=(rho+satRho)/2;
  rho=next>0?next:rho/2;
 }
 throw Error('D2O: не вдалося знайти густину для заданих p, T.');
}
function d2oPT(p,T){
 if(!Number.isFinite(p)||!Number.isFinite(T)||p<=0||T<=0||T>825||p>1200)throw Error('D2O (IAPWS R16-17): потрібно 0 < p ≤ 1200 МПа, 0 < T ≤ 825 K.');
 if(T<210)throw Error('D2O: фазова перевірка підтримує T ≥ 210 K; нижчі температури тут не реалізовані.');
 if(p>=.00066159&&T<=315){const m=meltingTemperature(p,'D2O');if(T<=m.T)throw Error(`D2O: тверда область або межа плавлення льоду ${m.phase} (Tm=${m.T.toFixed(6)} K); властивості твердої D2O не моделюються.`);}
 if(T<=276.97){
  let side='liquid';
  if(p<.00066159){if(p>=sublimationPressure(Math.min(T,276.969),'D2O'))throw Error('D2O: тверда область або межа сублімації; властивості твердої D2O не моделюються.');side='vapor';}
  const rho=d2oDensityAt(p,T,side==='liquid'?55:p*1000/(D2O_R*T));
  return {...d2oDecorate(T,rho),phase:side==='liquid'?'Стійка рідина':'Стійка пара',notes:[D2O_PHASE_NOTE]};
 }
 if(T<D2O_TC){
  const sat=d2oSaturation(T);
  const satRl=sat.liquid.rho/D2O_M, satRv=sat.vapor.rho/D2O_M;
  if(Math.abs(p-sat.p)<Math.max(1e-10,sat.p*1e-9))throw Error('D2O: на лінії насичення p–T не визначає фазу; оберіть режим насичення за T.');
  const side=p>=sat.p?'liquid':'vapor';
  const guess=side==='liquid'?satRl*1.01:satRv*(satRv>0?0.99:1);
  const rho=d2oDensityAt(p,T,guess,side,side==='liquid'?satRv:satRl);
  return {...d2oDecorate(T,rho),phase:side==='liquid'?'Стійка рідина':'Стійка пара',notes:[D2O_PHASE_NOTE]};
 }
 const guess=Math.max(p*1000/(D2O_R*T),D2O_RHOC*(p>D2O_RHOC*D2O_R*D2O_TC/1000?1.5:0.3));
 const rho=d2oDensityAt(p,T,guess);
 return d2oDecorate(T,rho);
}
function d2oMaxwellStep(T,rl,rv){
 const tau=D2O_TC/T;
 const phase=rho=>{const d=rho/D2O_RHOC,r=d2oPhiR(d,tau),o=d2oPhi0(d,tau);
  return {p:rho*(1+d*r.phi_d),g:1+o.phi+r.phi+d*r.phi_d,b:1+2*d*r.phi_d+d*d*r.phi_dd};};
 const residual=(l,v)=>{const L=phase(l),V=phase(v);return {L,V,f:L.p-V.p,g:L.g-V.g};};
 // Dividing by the phase separation prevents the trivial equal-density root
 // from satisfying convergence merely because both residuals approach zero.
 const norm=(q,l,v)=>Math.max(Math.abs(q.f),Math.abs(q.g)*D2O_RHOC)/(l-v);
 for(let i=0;i<100;i++){
  const q=residual(rl,rv),n=norm(q,rl,rv);
  if(rl>rv&&q.L.b>0&&q.V.b>0&&n<1e-11)return [rl,rv];
  // Analytic Jacobian: d(p/RT)/drho=b; d(g/RT)/drho=b/rho.
  const A=q.L.b,B=-q.V.b,C=A/rl,D=B/rv,det=A*D-B*C;
  if(!Number.isFinite(det)||det===0)return null;
  const dl=(-q.f*D+q.g*B)/det,dv=(-A*q.g+C*q.f)/det;
  let accepted=false;
  for(let scale=1;scale>=2**-24;scale/=2){
   const l=rl+scale*dl,v=rv+scale*dv;
   if(!(l>v&&v>0))continue;
   const next=residual(l,v);
   if(next.L.b>0&&next.V.b>0&&norm(next,l,v)<n){rl=l;rv=v;accepted=true;break;}
  }
  if(!accepted)return null;
 }
 return null;
}
// Anchor point from the official Table 8 (T=280 K), used as a known-good seed for the
// continuation below. Starting from a well phase-separated state and marching toward the
// target T tracks the true liquid/vapor branch; seeding directly near Tc instead lands on
// the spurious rl=rv trivial root, which also satisfies equal-p/equal-g but is unphysical.
const D2O_ANCHOR_T=280, D2O_ANCHOR_RL=55.2072786, D2O_ANCHOR_RV=0.353747143e-3;
function d2oSaturation(T){
 if(!Number.isFinite(T)||T<=276.97||T>=D2O_TC)throw Error('D2O (IAPWS R16-17): насичення визначено для 276,97 K < T < 643,847 K.');
 // Double precision cannot reliably distinguish coexisting phases arbitrarily
 // close to Tc. Report a numerical limit instead of publishing a spurious root.
 if(D2O_TC-T<1e-5)throw Error('D2O: надто близько до критичної точки для надійного розділення фаз (Tc − T < 0,00001 K).');
 let [rl,rv]=d2oMaxwellStep(D2O_ANCHOR_T,D2O_ANCHOR_RL,D2O_ANCHOR_RV);
 let current=D2O_ANCHOR_T;
 while(current!==T){
  const direction=Math.sign(T-current);
  let size=Math.min(Math.abs(T-current),2,direction>0?(D2O_TC-current)*0.15:2);
  let step=null,Tk;
  for(let retry=0;retry<30;retry++){
   Tk=size===Math.abs(T-current)?T:current+direction*size;
   step=d2oMaxwellStep(Tk,rl,rv);
   if(step)break;
   size/=2;
   if(size<1e-8)break;
  }
  if(!step)throw Error('D2O: не вдалося надійно розділити стійкі фази насичення для заданої температури.');
  [rl,rv]=step;current=Tk;
 }
 const liquid=d2oDecorate(T,rl), vapor=d2oDecorate(T,rv);
 if(!(liquid.rho>vapor.rho&&vapor.h>liquid.h&&liquid.cp>0&&vapor.cp>0&&Number.isFinite(liquid.w)&&Number.isFinite(vapor.w)))throw Error('D2O: рівновага не пройшла перевірку фізичної стійкості фаз.');
 return {model:liquid.model,T,p:(liquid.p+vapor.p)/2,liquid:{...liquid,phase:'Насичена рідина',x:0},vapor:{...vapor,phase:'Насичена пара',x:1},latentHeat:vapor.h-liquid.h};
}


// src/seawater.js
// IAPWS R13-08(2008), Release on the IAPWS Formulation 2008 for the Thermodynamic
// Properties of Seawater. g(S,T,p)=gW(T,p)+gS(S,T,p); gW reuses the verified IAPWS-95
// Helmholtz core (src/iapws95.js), gS is the saline-part Gibbs polynomial, Table 2/Eq.(4).
// Verified against all 3 official Table 8 check points (water/saline/seawater columns).

const SW_SN=0.03516504, SW_SSTAR=SW_SN*40/35, SW_TSTAR=40, SW_T0=273.15, SW_PSTAR=1e8, SW_P0=101325;

// Table 2 — 64 coefficients [i,j,k,g_ijk] of the saline part of the Gibbs function, Eq. (4).
const SW_G=[
[1,0,0,0.581281456626732e4],[2,0,0,0.141627648484197e4],[3,0,0,-0.243214662381794e4],
[4,0,0,0.202580115603697e4],[5,0,0,-0.109166841042967e4],[6,0,0,0.374601237877840e3],
[7,0,0,-0.485891069025409e2],[1,1,0,0.851226734946706e3],[2,1,0,0.168072408311545e3],
[3,1,0,-0.493407510141682e3],[4,1,0,0.543835333000098e3],[5,1,0,-0.196028306689776e3],
[6,1,0,0.367571622995805e2],[2,2,0,0.880031352997204e3],[3,2,0,-0.430664675978042e2],
[4,2,0,-0.685572509204491e2],[2,3,0,-0.225267649263401e3],[3,3,0,-0.100227370861875e2],
[4,3,0,0.493667694856254e2],[2,4,0,0.914260447751259e2],[3,4,0,0.875600661808945],
[4,4,0,-0.171397577419788e2],[2,5,0,-0.216603240875311e2],[4,5,0,0.249697009569508e1],
[2,6,0,0.213016970847183e1],[2,0,1,-0.331049154044839e4],[3,0,1,0.199459603073901e3],
[4,0,1,-0.547919133532887e2],[5,0,1,0.360284195611086e2],[2,1,1,0.729116529735046e3],
[3,1,1,-0.175292041186547e3],[4,1,1,-0.226683558512829e2],[2,2,1,-0.860764303783977e3],
[3,2,1,0.383058066002476e3],[2,3,1,0.694244814133268e3],[3,3,1,-0.460319931801257e3],
[2,4,1,-0.297728741987187e3],[3,4,1,0.234565187611355e3],[2,0,2,0.384794152978599e3],
[3,0,2,-0.522940909281335e2],[4,0,2,-0.408193978912261e1],[2,1,2,-0.343956902961561e3],
[3,1,2,0.831923927801819e2],[2,2,2,0.337409530269367e3],[3,2,2,-0.541917262517112e2],
[2,3,2,-0.204889641964903e3],[2,4,2,0.747261411387560e2],[2,0,3,-0.965324320107458e2],
[3,0,3,0.680444942726459e2],[4,0,3,-0.301755111971161e2],[2,1,3,0.124687671116248e3],
[3,1,3,-0.294830643494290e2],[2,2,3,-0.178314556207638e3],[3,2,3,0.256398487389914e2],
[2,3,3,0.113561697840594e3],[2,4,3,-0.364872919001588e2],[2,0,4,0.158408172766824e2],
[3,0,4,-0.341251932441282e1],[2,1,4,-0.316569643860730e2],[2,2,4,0.442040358308000e2],
[2,3,4,-0.111282734326413e2],[2,0,5,-0.262480156590992e1],[2,1,5,0.704658803315449e1],
[2,2,5,-0.792001547211682e1],
];
const SW_LOG=new Map(), SW_POLY=[];
for(const [i,j,k,g] of SW_G){if(i===1)SW_LOG.set(j+','+k,g);else SW_POLY.push({i,j,k,g});}

function salinePart(S,T,p){
 const xi=Math.sqrt(S/SW_SSTAR),lnxi=Math.log(xi),tau=(T-SW_T0)/SW_TSTAR,pi=(p-SW_P0)/SW_PSTAR;
 let g=0,gT=0,gp=0,gTT=0,gTp=0,gpp=0,gS=0,gSp=0;
 for(let k=0;k<=5;k++)for(let j=0;j<=6;j++){
  const g1=SW_LOG.get(j+','+k)||0;
  let B=g1*xi*xi*lnxi,Si=g1*(2*lnxi+1);
  for(const t of SW_POLY)if(t.j===j&&t.k===k){B+=t.g*xi**t.i;Si+=t.i*t.g*xi**(t.i-2);}
  const tauJ=tau**j,piK=pi**k;
  g+=B*tauJ*piK;if(j>=1)gT+=j*B*tau**(j-1)*piK;gS+=Si*tauJ*piK;
 }
 gT/=SW_TSTAR;gS/=2*SW_SSTAR;
 for(const {i,j,k,g:gijk} of SW_POLY){
  const xiI=xi**i,tauJ=tau**j;
  if(k>=1)gp+=k*gijk*xiI*tauJ*pi**(k-1);
  if(j>=2)gTT+=j*(j-1)*gijk*xiI*tau**(j-2)*pi**k;
  if(j>=1&&k>=1)gTp+=j*k*gijk*xiI*tau**(j-1)*pi**(k-1);
  if(k>=2)gpp+=k*(k-1)*gijk*xiI*tauJ*pi**(k-2);
  if(k>=1)gSp+=i*k*gijk*xi**(i-2)*tauJ*pi**(k-1);
 }
 gp/=SW_PSTAR;gTT/=SW_TSTAR*SW_TSTAR;gTp/=SW_TSTAR*SW_PSTAR;gpp/=SW_PSTAR*SW_PSTAR;gSp/=2*SW_SSTAR*SW_PSTAR;
 return {g,gT,gp,gTT,gTp,gpp,gS,gSp};
}

function swRhoLiquid(T,pMPa){
 let rho=1000;
 for(let i=0;i<200;i++){
  const q=raw95(T,rho),err=q.p-pMPa;
  if(Math.abs(err)<Math.max(1e-10,Math.abs(pMPa)*1e-10))return rho;
  const h=rho*1e-6,dp=(raw95(T,rho+h).p-raw95(T,rho-h).p)/(2*h);
  rho-=Math.max(-50,Math.min(50,err/dp));
  if(!(rho>1))rho=1000;
 }
 throw Error('Морська вода: не вдалося визначити густину частини H2O.');
}

// gW(T,p) and its T-p derivatives, from the already-verified IAPWS-95 Helmholtz core.
// (dv/dT)_p=v*alpha and (dv/dp)_T=-v^2*(drho/dp)_T come directly from raw95's analytic A/B terms.
function waterPart(T,p){
 const q=raw95(T,swRhoLiquid(T,p/1e6));
 const v=q.v,s=q.s*1000,h=q.h*1000,u=q.u*1000,cp=q.cp*1000;
 const g=h-T*s,f=u-T*s,gT=-s,gp=v,gTT=-cp/T,gTp=v*q.alpha,gpp=-v*v*q.drhodp/1e6;
 return {g,gT,gp,gTT,gTp,gpp,s,v,h,u,f,cp,w:q.w};
}

// R13-08 Eq. 26, 30, 32. Use the same Gibbs reference as IAPWS-95/ice Ih.
function swChemicalPotential(S,T,p){
 const W=waterPart(T,p);if(S===0)return W.g;
 const Sl=salinePart(S,T,p);return W.g+Sl.g-S*Sl.gS;
}
function swVaporG(T,p){
 let rho=p/(461.51805*T);
 for(let i=0;i<60;i++){const q=raw95(T,rho),err=q.p-p/1e6;
  if(q.drhodp>0&&Math.abs(err)<Math.max(1e-13,p/1e6*1e-10))return 1000*(q.h-T*q.s);
  const next=rho-err*q.drhodp;
  if(!(next>0)||!Number.isFinite(next)||q.drhodp<=0)throw Error('Морська вода: не знайдено стійку парову фазу.');
  rho=next;
 }
 throw Error('Морська вода: парова рівновага не збіглася.');
}
function seawaterFreezingTemperature(S,p){
 if(!Number.isFinite(S)||S<0||S>.12||!Number.isFinite(p)||p<611.655||p>1e8)throw Error('Замерзання морської води: некоректна солоність або тиск.');
 let lo=261,hi=273.16;
 const f=T=>swChemicalPotential(S,T,p)-ice(T,p).g;
 if(f(lo)*f(hi)>0)throw Error('Замерзання: корінь поза підтримуваними 261…273,16 K.');
 for(let i=0;i<55;i++){const mid=(lo+hi)/2;if(f(mid)>0)lo=mid;else hi=mid;}
 return (lo+hi)/2;
}
function seawaterBoilingPressure(S,T){
 if(!Number.isFinite(S)||S<0||S>.12||!Number.isFinite(T)||T<265||T>353)throw Error('Кипіння морської води: потрібно S=0…0,12 кг/кг і T=265…353 K.');
 let lo=Math.log(1),hi=lo;
 const f=p=>swChemicalPotential(S,T,p)-swVaporG(T,p);
 while(f(Math.exp(hi))>0&&Math.exp(hi)<101325)hi+=Math.log(1.15);
 if(Math.exp(hi)>101325||f(Math.exp(lo))*f(Math.exp(hi))>0)throw Error('Кипіння: корінь поза підтримуваним діапазоном тиску.');
 for(let i=0;i<55;i++){const mid=(lo+hi)/2;if(f(Math.exp(mid))>0)lo=mid;else hi=mid;}
 return Math.exp((lo+hi)/2);
}
function seawaterBoundary(kind,S,value){
 if(!['freeze','boil'].includes(kind))throw Error('Невідома фазова рівновага морської води.');
 const T=kind==='freeze'?seawaterFreezingTemperature(S,value):value;
 const p=kind==='freeze'?value:seawaterBoilingPressure(S,T);
 return {boundary:true,model:'IAPWS R13-08 · рівновага Eq. '+(kind==='freeze'?'32':'30'),S,T,p,phase:kind==='freeze'?'Морська вода ↔ лід Ih':'Морська вода ↔ пара H₂O',notes:['Чисельна рівновага хімічних потенціалів; без наближеної формули фазової межі.']};
}

// S: absolute salinity kg/kg, T: K (ITS-90), p: Pa.
function seawater(S,T,p){
 if(!Number.isFinite(S)||!Number.isFinite(T)||!Number.isFinite(p)||S<0||S>0.12||T<265||T>353||p<611.655||p>1e8)
  throw Error('Морська вода (IAPWS R13-08): обчислювальні межі 0 ≤ S ≤ 0,12 кг/кг, 265…353 K (фазові межі перевіряються окремо), 611,655 Па ≤ p ≤ 10⁸ Па.');
 const W=waterPart(T,p);
 if(S===0)return decorate(S,T,p,W,{g:0,gT:0,gp:0,gTT:0,gTp:0,gpp:0,gS:0,gSp:0},W);
 const Sl=salinePart(S,T,p);
 const tot={g:W.g+Sl.g,gT:W.gT+Sl.gT,gp:W.gp+Sl.gp,gTT:W.gTT+Sl.gTT,gTp:W.gTp+Sl.gTp,gpp:W.gpp+Sl.gpp};
 return decorate(S,T,p,W,Sl,tot);
}
function decorate(S,T,p,W,Sl,tot){
 const v=W.v+Sl.gp,s=W.s-Sl.gT,h=W.h+(Sl.g-T*Sl.gT),u=h-p*v,f=u-T*s,cp=-T*tot.gTT;
 const rho=1/v,w2=-v*v*tot.gTT/(tot.gpp*tot.gTT-tot.gTp*tot.gTp),w=w2>0?Math.sqrt(w2):null;
 const muW=tot.g-S*Sl.gS;
 const warnings=[];
 let phase='Стійка рідина';
 const boilingP=seawaterBoilingPressure(S,T);
 if(p<boilingP*(1-1e-7)){phase='Метастабільна перегріта рідина';warnings.push('Тиск нижче рівноважного тиску кипіння (Eq. 30): задана рідина нестійка щодо випаровування.');}
 else if(Math.abs(p-boilingP)<boilingP*1e-7)phase='Межа кипіння: рідина ↔ пара';
 const iceDifference=T<=273.16?muW-ice(T,p).g:null;
 if(iceDifference!==null&&Math.abs(iceDifference)<=1e-5)phase='Межа замерзання: рідина ↔ лід Ih';
 if(iceDifference!==null&&iceDifference>1e-5){
  phase='Метастабільна переохолоджена рідина';
  warnings.push('Метастабільний стан: хімічний потенціал води перевищує енергію Гіббса льоду Ih (IAPWS R13-08, Eq. 32). Таблиця описує переохолоджену рідину, а не рівноважний стан.');
 }
 if(S>0&&!(T<=313&&S<=(p>=SW_P0?0.042:0.05)))warnings.push('Густина, питомий об’єм і швидкість звуку: екстраполяція поза областями A/B IAPWS R13-08; достовірність цих властивостей не гарантована.');
 const invalidDerivatives=S>0&&T+450*S>362;
 if(invalidDerivatives)warnings.push('Область F: T/K + 450·S/(кг/кг) > 362. Похідні густини та швидкість звуку можуть бути нефізичними; не використовуйте їх для інженерних розрахунків.');
 if(w===null)warnings.push('Швидкість звуку недоступна: рівняння дало недодатне значення w², дійсний результат відсутній.');
 if(S>0&&p!==SW_P0&&(S>0.042||T>313))warnings.push('Екстраполяція термічних властивостей: область C для високої солоності/температури визначена при атмосферному тиску 101325 Па.');

 return {model:'IAPWS R13-08',S,T,p,g:tot.g,v,rho,s,h,u,f,cp,w,muW,boilingP,phase,notes:warnings,invalidDerivatives};
}


// src/glossary.js
// Plain-language, example-driven explanations for students meeting these terms for the
// first time. Not a substitute for a textbook -- short, intuitive, with everyday analogies
// where they help. GLOSSARY is keyed by canonical property key (used directly by the main
// property table). LABEL_GLOSSARY maps the descriptive Ukrainian labels used in the other
// learning panels (gases/humid air/ice/D2O/seawater/cycles) back to the same GLOSSARY keys,
// so one explanation is reused everywhere the same physical quantity appears.
const GLOSSARY={
 pgauge:'Манометричний тиск — різниця абсолютного й місцевого атмосферного тисків: pман = pабс − pатм. Від’ємне значення означає розрідження; рівняння властивостей використовують абсолютний тиск.',
 p:'Сила, з якою частинки речовини «штовхають» на кожен квадратний сантиметр стінки посудини чи труби. Уявіть натовп у кімнаті: що щільніше людей притиснуто до стін, то більший тиск. Абсолютний тиск визначає температуру кипіння: що вищий тиск, то вища точка кипіння — у скороварці вода кипить не при 100°C, а вище.',
 T:'Наскільки «швидко» в середньому рухаються молекули речовини: гарячіше — швидше, холодніше — повільніше. У таблиці показана в °C для зручності, але формули завжди використовують шкалу Кельвіна (°C + 273,15), де 0 K — найхолодніший можливий стан, коли рух молекул практично зупиняється.',
 rho:'Скільки кілограмів речовини вміщується в одному кубічному метрі — наскільки «щільно упаковані» молекули. Пара в сотні разів легша за рідку воду, тому для тієї самої маси вона займає набагато більший об’єм.',
 v:'Скільки місця (м³) займає рівно 1 кілограм речовини — обернена величина до густини. З’являється у формулах роботи, бо «робота = тиск × зміна об’єму».',
 h:'Зручна «бухгалтерська» енергія для процесів при сталому тиску — а в теплоенергетиці майже все рахують саме так (турбіни, котли, теплообмінники). Поєднує внутрішню енергію речовини й «роботу», яку довкілля виконує, щоб впихнути цю речовину в систему при даному тиску. Різниця ентальпій на вході й виході турбіни — це і є енергія, яку турбіна забрала.',
 s:'Міра «безладу» чи розсіяної енергії в речовині — складно уявити напряму, та є просте правило: в ідеальному процесі без втрат (ідеальна турбіна) ентропія не змінюється, а в реальному процесі з тертям вона завжди зростає. Тому за ентропією можна оцінити, наскільки реальний процес «гірший» за ідеальний.',
 u:'Уся енергія, «захована» всередині речовини через рух і взаємне притягання її молекул — як енергія в стисненій пружині, лише на молекулярному рівні. На відміну від ентальпії, тут не враховано енергію, пов’язану з тиском і об’ємом ззовні.',
 cp:'Скільки тепла (кДж) треба підвести до 1 кг речовини, щоб вона нагрілась на 1 градус, якщо тиск весь час однаковий. Чим більша cp, тим «важче» нагріти речовину — вода має дуже високу теплоємність, тому повільно нагрівається й повільно остигає.',
 cv:'Те саме, що й cp, але якщо об’єм посудини зафіксований і змінюватись не може. Завжди трохи менша за cp, бо при сталому об’ємі жодна частина тепла не йде на «розштовхування» стінок посудини.',
 w:'З якою швидкістю маленьке збурення тиску (звукова хвиля) пробігає крізь речовину. У турбінах важливо: пара не може текти крізь сопло швидше за власну швидкість звуку (так зване «запирання» потоку).',
 ex:'Скільки корисної роботи максимум можна «видобути» з потоку речовини, давши йому охолонути й розширитися аж до умов довкілля (кімнатна температура й атмосферний тиск). Чесніша оцінка «цінності» потоку, ніж просто ентальпія, бо враховує принципово недосяжну частину енергії.',
 x:'Яка частка маси суміші пари й води — це пара, а яка ще рідина. x=0 — щойно почала закипати (ще вся рідина), x=1 — википіла повністю (вже вся пара). x=0,5 означає, що рівно половина маси — пара, половина — краплі рідини.',
 region:'Технічна «адреса»: яке з п’яти рівнянь стандарту IAPWS-IF97 використане для цієї точки. 1 — стиснена рідина, 2 — перегріта пара, 3 — зона біля критичної точки (де рідина й пара стають «невідрізнюваними»), 4 — межа кипіння/конденсації, 5 — дуже висока температура.',
 isentropic:'Технічний коефіцієнт κs: наскільки сильно змінюється тиск, якщо трохи стиснути чи розширити речовину без обміну теплом із довкіллям. Використовується в розрахунках сопел і швидкості звуку.',
 A:'Теоретична величина: максимальна корисна робота, яку можна отримати з речовини, якщо її температура й об’єм лишаються незмінними. На практиці рідко рахують напряму — радше «будівельний матеріал» для виведення інших формул.',
 G:'Схожа на енергію Гельмгольца, але для умов сталої температури й тиску — саме такі умови найчастіше трапляються в житті. На лінії кипіння/конденсації енергія Гіббса рідини й пари рівно однакова — це і є фізична причина, чому вони можуть існувати в рівновазі одна з одною.',
 Z:'Наскільки реальна поведінка речовини відрізняється від «ідеального газу» зі шкільної фізики (pV=nRT). Z=1 — речовина поводиться точно як ідеальний газ. Z помітно відмінний від 1 — молекули «відчувають» одна одну (тяжіють чи відштовхуються), і шкільну формулу застосовувати не можна.',
 alpha:'Наскільки сильно розширюється речовина, нагріта на 1 градус при сталому тиску. Через це ртуть піднімається в термометрі, а рейки кладуть із зазорами — більшість речовин трохи «розпухає» від тепла.',
 kappa:'Наскільки легко речовину стиснути: наскільки зменшується її об’єм при зростанні тиску й сталій температурі. Гази стискаються легко (велика κT), рідини й тверді тіла — майже ні (дуже мала κT).',
 dvdt:'Технічна величина для точних розрахунків: наскільки зміниться питомий об’єм, якщо трохи підняти температуру при сталому тиску. Не «називана» властивість сама по собі, а інструмент для обчислення чутливості процесу.',
 dvdp:'Технічна величина: наскільки зміниться питомий об’єм, якщо трохи підняти тиск при сталій температурі. Та сама ідея, що й ізотермічна стисливість κT, лише в іншій формі запису.',
 dpdt:'Технічна величина: наскільки зміниться тиск, якщо трохи підняти температуру в герметично закритій, нерозширюваній посудині. Застосовується, зокрема, у формулі ефекту Джоуля–Томсона.',
 dpdv:'Технічна величина: наскільки зміниться тиск при малій зміні питомого об’єму й сталій температурі. Для будь-якої стабільної речовини завжди від’ємна — стиснути речовину завжди означає підняти тиск, ніколи навпаки.',
 ijt:'Допоміжна технічна величина δT, пов’язана зі звичайним ефектом Джоуля–Томсона (нижче): показує зміну ентальпії, а не температури, у тому самому процесі дроселювання.',
 jt:'Наскільки зміниться температура газу чи пари, пропущених крізь вузьке звуження (вентиль, дросель) без підведення тепла й без роботи. Для водяної пари зазвичай додатний — пара охолоджується при дроселюванні. Саме цей ефект лежить в основі побутового холодильника.',
 dc:'У скільки разів вода послаблює електричне поле всередині себе порівняно з вакуумом. Встроміть шматок води в електричне поле — воно всередині стане значно слабшим. Важливо для датчиків рівня, хімічного аналізу й електрообладнання, що контактує з водою чи парою.',
 mu:'Наскільки речовина чинить опір течії — наскільки важко змусити один шар рідини чи пари ковзати повз сусідній. Мед в’язкіший за воду, вода в’язкіша за повітря. Чим вища в’язкість, тим більше енергії втрачається на тертя в трубі.',
 nu:'Та сама в’язкість, поділена на густину — зручніша форма для деяких формул гідродинаміки, наприклад числа Рейнольдса, яке визначає, чи потік плавний (ламінарний), чи з вихорами (турбулентний).',
 lambda:'Наскільки добре речовина передає тепло крізь себе без переміщення самої речовини (на відміну від конвекції, де тепло переносить рух гарячих мас рідини). Метал швидко нагрівається на плиті (висока λ), повітря — ізолятор (низька λ).',
 diffusivity:'Наскільки швидко «хвиля» зміни температури поширюється всередині речовини. Висока температуропровідність — речовина швидко вирівнює температуру по всьому об’єму; низька — гарячі й холодні ділянки довго тримаються поруч.',
 Pr:'Безрозмірне число: що «перемагає» в речовині — поширення руху (в’язкість) чи поширення тепла (температуропровідність). Визначає форму профілю швидкості й температури біля гарячої стінки теплообмінника.',
 sigma:'Сила, що «стягує» поверхню рідини, мов натягнута плівка — тому крапля роси кругла, а деякі комахи «ходять» по воді. У котлах впливає на те, як утворюються й відриваються бульбашки пари при кипінні.',
 M:'Маса одного моля речовини (6,022×10²³ молекул) у грамах чи кілограмах на кіломоль — наскільки «важка» одна молекула порівняно з іншими. У суміші газів впливає, скільки «важить» кожен компонент у загальній масі.',
 gamma:'Відношення двох теплоємностей Cp/Cv — наскільки «важче» нагріти газ при сталому тиску, ніж при сталому об’ємі. Для повітря приблизно 1,4. Визначає поведінку газу у швидких (адіабатичних) процесах стиснення й розширення — у компресорах і турбінах.',
 RH:'Наскільки повітря «заповнене» водяною парою порівняно з максимумом, який воно може утримати при цій температурі, у відсотках. 100% — повітря насичене (далі туман чи роса); 0% — повітря повністю сухе. Тепле повітря утримує більше пари, ніж холодне.',
 W:'Скільки кілограмів водяної пари припадає на 1 кілограм абсолютно сухого повітря. На відміну від відносної вологості (у відсотках), це абсолютна кількість вологи — не змінюється, коли повітря просто нагрівають чи охолоджують без додавання/видалення вологи.',
 pv:'Який тиск створювала б сама водяна пара, якби в посудині більше нічого не було — уявіть, що все повітря прибрали, лишили тільки пару. Сума парціального тиску пари й парціального тиску сухого повітря дає загальний тиск суміші.',
 dew:'Температура, до якої треба охолодити вологе повітря, щоб пара в ньому почала конденсуватись у краплі — так вранці на траві з’являється роса, а на холодній склянці з напоєм — запітніння. Чим вологіше повітря, тим вища точка роси.',
 wet:'Температура, яку показав би термометр, обгорнутий вологою тканиною, що обдувається повітрям (вода з тканини випаровується й охолоджує термометр). Сухіше повітря довкола — сильніше випаровування — нижча ця температура порівняно зі звичайним («сухим») термометром.',
 beta:'Наскільки сильно зростає тиск усередині речовини, нагрітої в абсолютно герметичній жорсткій посудині, де об’єм не може змінитись. Тому заповнена по вінця й щільно закрита пляшка з рідиною може тріснути від нагрівання.',
 S:'Скільки грамів солей розчинено в кожному кілограмі морської води. Морська вода в середньому має солоність близько 35 г/кг (3,5% маси — розчинені солі, здебільшого звичайна кухонна сіль).',
 muW:'Технічна величина з термодинаміки розчинів: наскільки «охоче» молекули чистої води переходять у розчин чи виходять із нього — визначає напрямок осмосу й випаровування/кристалізації. Що солоніша вода, то нижчий цей показник.',
 turbineWork:'Скільки корисної механічної енергії (на 1 кг пари) турбіна забирає з пари, що проходить крізь неї, обертаючи вал генератора. Чим більша різниця тиску й температури між входом і виходом, тим більше роботи можна отримати.',
 compressorWork:'Скільки енергії (на 1 кг речовини) треба витратити, щоб підняти тиск рідини насосом чи газу компресором. Це енергія, яку ми вкладаємо в систему — на відміну від роботи турбіни, яку ми з системи забираємо.',
 heatIn:'Скільки теплової енергії (на 1 кг робочого тіла) підводиться до циклу — зазвичай у котлі чи парогенераторі, де паливо чи інше джерело тепла перетворює воду на пару високого тиску.',
 heatOut:'Скільки теплової енергії (на 1 кг робочого тіла) цикл віддає назовні — зазвичай у конденсаторі, де відпрацьована пара охолоджується назад до рідкого стану перед поверненням у насос.',
 netWork:'Різниця між тим, що турбіна виробила, і тим, що насос чи компресор спожив — фактична корисна енергія, яку цикл віддає назовні (наприклад, електрогенератору). Саме її ділять на підведене тепло, щоб порахувати ККД циклу.',
 efficiency:'Яка частка підведеного тепла перетворюється на корисну роботу, у відсотках. Решта неминуче «втрачається» у відведене тепло конденсатора. Жоден реальний тепловий цикл не може мати ККД 100% — це фундаментальне обмеження другого закону термодинаміки, не недолік конкретної конструкції.',
 power:'Скільки енергії цикл виробляє чи споживає за секунду (кіловати = кілоджоулі за секунду) — залежить і від роботи на кожен кілограм робочого тіла, і від того, скільки кілограмів проходить через установку щосекунди (масової витрати).',
};

// Descriptive Ukrainian labels used by the other learning panels -> canonical GLOSSARY key.
const LABEL_GLOSSARY={
 'T':'T','P':'p','M':'M','h':'h','s':'s','u':'u','ρ':'rho','v':'v','Cp':'cp','Cv':'cv','w':'w',
 'Cp/Cv':'gamma','Z':'Z','В’язкість':'mu','Теплопровідність':'lambda','Сухість':'x',
 'Тиск':'p','Температура':'T','Відносна вологість':'RH','Вологовміст W':'W','Парціальний Pᵥ':'pv',
 'Ентальпія':'h','Питомий об’єм':'v','Густина суміші':'rho','Точка роси':'dew','Мокрий термометр':'wet',
 'Густина':'rho','Питома ентальпія':'h','Питома внутрішня енергія':'u','Енергія Гельмгольца':'A',
 'Енергія Гіббса':'G','Питома ентропія':'s','Питома теплоємність cp':'cp',
 'Кубічний коеф. розширення α':'alpha','Коефіцієнт тиску β':'beta','Ізотермічна стисливість κT':'kappa',
 'Ізентропна стисливість κs':'isentropic','Ізохорна теплоємність cv':'cv','Ізобарна теплоємність cp':'cp',
 'Швидкість звуку':'w','Абсолютна солоність':'S','Хімічний потенціал води μW':'muW',
 'Робота турбіни':'turbineWork','Робота насоса / компресора':'compressorWork','Підведене тепло':'heatIn',
 'Відведене тепло':'heatOut','Корисна робота':'netWork','Термічний ККД':'efficiency','Потужність':'power',
};


// src/input-guidance.js
const INPUT_GUIDANCE={
 pt:'Відомі абсолютний тиск і температура. Підходить для рідини або перегрітої пари. На насиченні ці два параметри залежні: для суміші потрібна сухість або інший незалежний параметр.',
 ph:'Відомі тиск і питома ентальпія. Зручно після нагрівання або дроселювання; температура й сухість визначаються з цих входів.',
 ps:'Відомі тиск і питома ентропія. Для ідеального ізоентропного розширення або стиснення використайте ентропію початкового стану й новий тиск.',
 satp:'Відомий тиск насичення. Показує окремо киплячу воду (x = 0) і суху насичену пару (x = 1); склад суміші не задається.',
 satt:'Відома температура насичення. Показує тиск, киплячу воду (x = 0) і суху насичену пару (x = 1).',
 px:'Відомі тиск і сухість. x — масова частка пари: 0 означає киплячу воду, 1 — суху насичену пару. Для 0 < x < 1 отримуємо рівноважну суміш. У критичній точці x невизначений.',
 tx:'Відомі температура насичення й сухість. x — масова частка пари 0…1 або 0…100%. У критичній точці сухість невизначена.',
 hs:'Відомі питомі ентальпія й ентропія. Тиск і температура визначаються чисельно; цей режим зручний для перевірки точки на h–s діаграмі.',
 pv:'Відомі тиск і питомий об’єм. Якщо задані загальний об’єм V та маса m, спочатку знайдіть v = V/m. Густина ρ = 1/v.',
 tv:'Відомі температура й питомий об’єм. Для закритої жорсткої посудини v зберігається при незмінній масі; знайдіть другий стан за новою температурою.',
 prho:'Відомі тиск і густина. Використовуйте густину в кг/м³, а не питомий об’єм; ρ = 1/v.',
 trho:'Відомі температура й густина. Поблизу фазових меж можуть існувати кілька станів: перевіряйте показані альтернативи.',
 pu:'Відомі тиск і питома внутрішня енергія. Для SI u = h − 1000·p·v, якщо p задано в МПа, v у м³/кг, h та u в кДж/кг.',
 tu:'Відомі температура й питома внутрішня енергія; тиск визначається чисельно.',
 th:'Відомі температура й питома ентальпія. Ця пара може мати кілька розв’язків; вибирайте стан за фізичними умовами задачі.',
 ts:'Відомі температура й питома ентропія. Допомагає знайти стан на перетині ізотерми й ізоентропи; можливі альтернативні розв’язки.',
 us:'Відомі питомі внутрішня енергія й ентропія. Обидві величини задаються на одиницю маси.',
 vs:'Відомі питомий об’єм і ентропія. Підходить для пошуку кінця ідеального ізоентропного процесу за заданим об’ємом.',
 hv:'Відомі питомі ентальпія й об’єм. Тиск, температура й фаза визначаються чисельно.',
 uv:'Відомі питомі внутрішня енергія й об’єм. Зручно для закритої жорсткої посудини після заданої зміни внутрішньої енергії.'
};
function modeGuidance(mode){const text=INPUT_GUIDANCE[mode]||'';return text+(!['pt','satp','satt','px','tx'].includes(mode)?' Знайдені альтернативні стани показуються окремо; чисельний пошук не гарантує всіх близьких або дотичних коренів.':'');}


// src/app.js
const $=id=>document.getElementById(id);
// Small original inline-SVG icon set (stroke, currentColor) - no external assets, nothing from the reference site.
